package net.hivel.islandsrpg.data;
import net.hivel.islandsrpg.quest.QuestProgress; import net.hivel.islandsrpg.stats.StatType; import java.util.*;
public class PlayerData { public final UUID uuid; public String name; public int level=1; public long xp=0,money=0,fragments=0; public int statPoints=0; public final EnumMap<StatType,Integer> stats=new EnumMap<>(StatType.class); public final Map<String, QuestProgress> activeQuests=new LinkedHashMap<>(); public final Set<String> completedQuests=new LinkedHashSet<>(); public final Map<String,Integer> kills=new HashMap<>(), bossKills=new HashMap<>(); public final Set<String> unlockedIslands=new LinkedHashSet<>(); public PlayerData(UUID uuid,String name){this.uuid=uuid;this.name=name; for(StatType t:StatType.values())stats.put(t,0); unlockedIslands.add("starter");} public int stat(StatType t){return stats.getOrDefault(t,0);} public void addStat(StatType t,int amount){stats.put(t, stat(t)+amount);} }
